#include <iostream>
#include <string>
#include <algorithm>
using namespace std;
const int N = 100010;
int h[N], ph[N], hp[N], sz, idx;
void heap_swap(int a, int b) {
    swap(ph[hp[a]], ph[hp[b]]);
    swap(hp[a], hp[b]);
    swap(h[a], h[b]);
}
void down(int u) {
    int t = u;
    if (u * 2 <= sz && h[u * 2] < h[t]) t = u * 2;
    if (u * 2 + 1 <= sz && h[u * 2 + 1] < h[t]) t = u * 2 + 1;
    if (u != t) { heap_swap(u, t); down(t); }
}
void up(int u) {
    while (u / 2 && h[u / 2] > h[u]) { heap_swap(u, u / 2); u /= 2; }
}
int main() {
    int m;
    scanf("%d", &m);
    while (m--) {
        string op;
        cin >> op;
        if (op == "I") {
            int x; scanf("%d", &x);
            sz++; idx++;
            ph[idx] = sz; hp[sz] = idx;
            h[sz] = x;
            up(sz);
        } else if (op == "PM") {
            printf("%d\n", h[1]);
        } else if (op == "DM") {
            heap_swap(1, sz); sz--; down(1);
        } else if (op == "D") {
            int k; scanf("%d", &k);
            int u = ph[k];
            heap_swap(u, sz); sz--;
            down(u); up(u);
        } else if (op == "C") {
            int k, x; scanf("%d%d", &k, &x);
            int u = ph[k];
            h[u] = x;
            down(u); up(u);
        }
    }
    return 0;
}
